/**
 * Credential storage utility using Browser Credential Management API
 * Provides secure storage of username and password credentials
 */

type CredentialData = {
  username: string;
  password: string;
};

/**
 * Check if Credential Management API is available
 */
const isCredentialManagementSupported = (): boolean => {
  return (
    typeof window !== `undefined` &&
    `credentials` in navigator &&
    `store` in navigator.credentials &&
    `get` in navigator.credentials
  );
};

/**
 * Save credentials to browser's credential manager
 * @param username - Username to save
 * @param password - Password to save
 * @returns Promise that resolves when credentials are saved
 */
export const saveCredentials = async (
  username: string,
  password: string,
): Promise<void> => {
  if (!isCredentialManagementSupported()) {
    console.warn(`Credential Management API is not supported in this browser`);
    return;
  }

  try {
    const credential = new PasswordCredential({
      id: username,
      password,
      name: username, // Display name for the credential
    });

    await navigator.credentials.store(credential);
  } catch (error) {
    console.error(`Failed to save credentials:`, error);
    throw error;
  }
};

/**
 * Load saved credentials from browser's credential manager
 * @returns Promise that resolves with credentials or null if none found
 */
export const loadCredentials = async (): Promise<CredentialData | null> => {
  if (!isCredentialManagementSupported()) {
    console.warn(`Credential Management API is not supported in this browser`);
    return null;
  }

  try {
    const credential = await navigator.credentials.get({
      password: true,
      mediation: `silent`, // Don't show browser UI, fail silently if no credentials
    });

    if (credential && credential instanceof PasswordCredential) {
      return {
        username: credential.id,
        password: credential.password || ``,
      };
    }

    return null;
  } catch (error) {
    // User cancelled or no credentials found - this is expected
    if (
      error instanceof Error &&
      (error.name === `NotAllowedError` ||
        error.name === `NotFoundError` ||
        error.message.includes(`No credential`))
    ) {
      return null;
    }
    console.error(`Failed to load credentials:`, error);
    return null;
  }
};

/**
 * Clear saved credentials from browser's credential manager
 * Note: The Credential Management API doesn't provide a direct way to delete credentials.
 * This function attempts to prevent autofill by storing an empty credential.
 * The user would need to manually delete credentials from browser settings.
 */
export const clearCredentials = async (): Promise<void> => {
  if (!isCredentialManagementSupported()) {
    console.warn(`Credential Management API is not supported in this browser`);
    return;
  }

  try {
    // Try to get existing credentials first
    const existingCredential = await navigator.credentials.get({
      password: true,
      mediation: `silent`,
    });

    if (existingCredential && existingCredential instanceof PasswordCredential) {
      // Note: There's no direct delete API, but we can prevent future autofill
      // by not storing credentials when user unchecks the box
      // The actual deletion would need to be done through browser settings
      console.log(
        `Credentials exist but cannot be programmatically deleted. User should clear them from browser settings.`,
      );
    }
  } catch (error) {
    // No credentials found or error - this is fine
    console.log(`No credentials to clear`);
  }
};

